    "format": "openapi-3.1",
    "title": "Meridian Transit Cloud \u2014 a SaaS API for regional public-transit agencies to publish real-time vehicle positions, trip updates, and rider-facing alerts. API",
    "served_at": "/openapi.json",
    "description": "OpenAPI 3.1 spec for the Meridian Transit Cloud \u2014 a SaaS API for regional public-transit agencies to publish real-time vehicle positions, trip updates, and rider-facing alerts. API, inlined below. All endpoints are relative paths on the same host; construct requests with execute().",
    "document": {
      "openapi": "3.1.0",
      "info": {
        "title": "Meridian Transit Cloud \u2014 a SaaS API for regional public-transit agencies to publish real-time vehicle positions, trip updates, and rider-facing alerts. API",
        "version": "1.0.0",
        "description": "Meridian Transit API: a multi-tenant REST service exposing GTFS-Realtime-derived feeds (vehicle positions, trip delays, service alerts) plus an authoring surface for agency operators to push alerts. Auth is OAuth2 client_credentials with short-lived bearer tokens scoped per agency."
      },
      "servers": [
        {
          "url": "http://localhost:9001"
        }
      ],
      "paths": {
        "/openapi.json": {
          "get": {
            "summary": "OpenAPI spec doc",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v3/oauth/token": {
          "post": {
            "summary": "OAuth2 client_credentials token",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v1/auth/token": {
          "post": {
            "summary": "Legacy token endpoint (deprecated)",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v3/agencies/me": {
          "get": {
            "summary": "Whoami / token introspection",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/vehicle-positions": {
          "get": {
            "summary": "List live vehicle positions",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/trip-updates": {
          "get": {
            "summary": "List trip delays",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/service-alerts": {
          "get": {
            "summary": "List published service alerts",
            "security": [
              {
                "bearer": []
              }
            ]
          },
          "post": {
            "summary": "Publish a service alert",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        }
      }
    }
  },
  "updated_at": "2026-06-29T19:42:42.872421+00:00"
}

